import{Client as a}from"pg";async function c(){let n=process.env.DATABASE_URL;if(!n){console.error("DATABASE_URL is not set (see .env.example)"),process.exitCode=1;return}let e=new a({connectionString:n});await e.connect();try{if((await e.query("SELECT 1 AS one")).rows[0]?.one!==1)throw new Error("SELECT 1 failed");let t=await e.query("SHOW server_version");console.log(`connected, server_version=${t.rows[0]?.server_version}`);let o=(await e.query(`SELECT table_name FROM information_schema.tables\

       WHERE table_schema = 'public' ORDER BY table_name`)).rows.map(s=>s.table_name);console.log(`tables (${o.length}): ${o.join(", ")}`);let r=["accounts","messages","financial_events","reminders","message_embeddings"].filter(s=>!o.includes(s));if(r.length>0)throw new Error(`missing expected tables: ${r.join(", ")} (run npm run migrate first)`);let i=await e.query("SELECT count(*)::int AS count FROM schema_migrations");console.log(`schema_migrations rows: ${i.rows[0]?.count}`),console.log("SMO\
KE OK")}finally{await e.end()}}c().catch(n=>{console.error(`SMOKE FAILED: ${n.message}`),process.exitCode=1});
